import json
pricing = json.load(open('er005_output/cost_baseline_01/pricing_snapshot.json', encoding='utf-8'))['prices']
def price(provider, model, meter, tier='Standard'):
    for p in pricing:
        if p['provider']==provider and p['model']==model and p['meter']==meter and p.get('tier','Standard')==tier:
            return p['price']
    raise KeyError((provider, model, meter, tier))
def cost(model, it, ot, ct=0, wsc=0):
    billable_in = max(it-ct,0)
    c = (billable_in/1e6)*price('openai',model,'input_tokens') + (ct/1e6)*price('openai',model,'cached_input_tokens') + (ot/1e6)*price('openai',model,'output_tokens')
    c += (wsc/1000)*price('openai','N/A (tool, all models)','web_search_call')
    return c*160

recs = [json.loads(l) for l in open('er013_output/family_c_future_trial_01/raw_usage_log.jsonl', encoding='utf-8') if l.strip()]
by_stage = {}
for r in recs:
    c = cost(r.get('model_id') or r.get('model'), r.get('input_tokens') or 0, r.get('output_tokens') or 0, r.get('cached_input_tokens') or 0, r.get('web_search_call_count') or 0)
    by_stage.setdefault(r.get('stage'), 0)
    by_stage[r.get('stage')] += c
for k,v in by_stage.items():
    print(k, round(v,2))
print('TOTAL', round(sum(by_stage.values()),2))
