import re, html

md = open('er013_output/family_c_future_trial_02/comparison.md', encoding='utf-8').read()
lines = md.split(chr(10))
out = []
in_code = False
in_table = False
i = 0
while i < len(lines):
    line = lines[i]
    if line.startswith('\`\`\`'):
        if not in_code:
            out.append('<pre>')
            in_code = True
        else:
            out.append('</pre>')
            in_code = False
        i += 1
        continue
    if in_code:
        out.append(html.escape(line))
        i += 1
        continue
    if line.startswith('# '):
        out.append(f'<h1>{html.escape(line[2:])}</h1>')
    elif line.startswith('## '):
        out.append(f'<h2>{html.escape(line[3:])}</h2>')
    elif line.startswith('### '):
        out.append(f'<h3>{html.escape(line[4:])}</h3>')
    elif line.startswith('|'):
        # simple markdown table handling
        if not in_table:
            out.append('<table>')
            in_table = True
            out.append('<tr>' + ''.join(f'<th>{html.escape(c.strip())}</th>' for c in line.strip(\"|\").split(\"|\")) + '</tr>')
            i += 1
            # skip separator line
            if i < len(lines) and re.match(r'^\|[\s\-:|]+\|$', lines[i]):
                i += 1
            continue
        else:
            out.append('<tr>' + ''.join(f'<td>{html.escape(c.strip())}</td>' for c in line.strip(\"|\").split(\"|\")) + '</tr>')
            i += 1
            continue
    else:
        if in_table:
            out.append('</table>')
            in_table = False
        if line.startswith('> '):
            out.append(f'<blockquote>{html.escape(line[2:])}</blockquote>')
        elif line.strip() == '':
            out.append('')
        else:
            out.append(f'<p>{html.escape(line)}</p>')
    i += 1
if in_table:
    out.append('</table>')
if in_code:
    out.append('</pre>')

body = chr(10).join(out)
page = f'''<!DOCTYPE html>
<html lang=\"ja\">
<head>
<meta charset=\"utf-8\">
<title>EDITORIAL-FUTURE-FAMILY-C-REDESIGN-TRIAL-02: 家庭用ロボットと家事</title>
